settings.customCss:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,600;1,700&family=Lato:ital,wght@0,300;0,400;0,700;1,400&display=swap');
.mfp.mfp-floral-youth{--fy-blush:#f2a7c0;--fy-blush-soft:#fce8f0;--fy-lav:#c8a8e0;--fy-lav-soft:#f0e8f8;--fy-lav-ink:#7a5a8c;--fy-rose:#e07090;--fy-ivory:#fdf6f0;--fy-cream:#f8efe7;--fy-ink:#3d2535;--fy-mut:#8d6a7a;--fy-line:#e8d5df;--fy-ring:rgba(242,167,192,.28);font-family:Lato,'Helvetica Neue',system-ui,sans-serif;color:var(--fy-ink)}
.mfp-floral-youth,.mfp-floral-youth *{box-sizing:border-box}
.mfp-floral-youth .ey-shell{display:grid;grid-template-columns:1fr;min-height:auto;max-width:1152px;margin:0 auto;background:var(--fy-ivory)}
/* ---------- HERO ---------- */
.mfp-floral-youth .ey-hero{display:none;position:relative;overflow:hidden;min-height:560px;background:var(--fy-ink)}
.mfp-floral-youth .ey-hero-media{position:absolute;inset:0}
.mfp-floral-youth .ey-hero-media img{display:block;width:100%;height:100%;object-fit:cover;opacity:.6}
.mfp-floral-youth .ey-hero-veil{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(61,37,53,.45) 0%,rgba(61,37,53,0) 40%,rgba(61,37,53,.85) 100%)}
.mfp-floral-youth .ey-floral-top{position:absolute;top:-8px;right:-8px;z-index:5;width:200px;opacity:.4;pointer-events:none}
.mfp-floral-youth .ey-floral-top svg{display:block;width:100%;height:auto}
.mfp-floral-youth .ey-hero-inner{position:relative;z-index:10;flex:1 1 auto;display:flex;flex-direction:column;justify-content:space-between;width:100%;min-height:520px;padding:36px}
.mfp-floral-youth .ey-brand{display:flex;align-items:center;gap:10px}
.mfp-floral-youth .ey-brand-icon{display:flex;align-items:center;justify-content:center;flex:0 0 36px;width:36px;height:36px;border-radius:12px;background:rgba(255,255,255,.15);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);color:#fff}
.mfp-floral-youth .ey-brand-icon svg{width:20px;height:20px}
.mfp-floral-youth .ey-brand span{font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.9)}
.mfp-floral-youth .ey-hero-copy{margin-top:auto}
.mfp-floral-youth .ey-dots{display:flex;align-items:center;gap:8px;margin-bottom:20px}
.mfp-floral-youth .ey-dots i{display:block;width:10px;height:10px;border-radius:999px;opacity:.8}
.mfp-floral-youth .ey-dots i:nth-child(1){background:var(--fy-blush)}
.mfp-floral-youth .ey-dots i:nth-child(2){background:var(--fy-lav)}
.mfp-floral-youth .ey-dots i:nth-child(3){background:var(--fy-rose)}
.mfp-floral-youth .ey-kicker{margin:0 0 8px;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--fy-blush)}
.mfp-floral-youth .ey-hero h1{margin:0;font-size:2.25rem;line-height:1.25;font-weight:700;letter-spacing:0}
.mfp.mfp-floral-youth .ey-hero h1{color:#fff!important}
.mfp-floral-youth .ey-hero h1 em{font-style:italic;font-weight:600}
.mfp-floral-youth .ey-hero-orn{display:flex;align-items:center;gap:12px;margin:16px 0}
.mfp-floral-youth .ey-hero-orn i{display:block;flex:1 1 auto;height:1px;background:rgba(255,255,255,.2)}
.mfp-floral-youth .ey-hero-orn svg{flex:0 0 14px;width:14px;height:14px;color:rgba(255,255,255,.5)}
.mfp-floral-youth .ey-sub{margin:0;font-size:14px;line-height:1.625;color:rgba(255,255,255,.75)}
.mfp-floral-youth .ey-stats{display:flex;align-items:center;gap:20px;margin-top:28px}
.mfp-floral-youth .ey-stats strong{display:block;font-size:24px;line-height:1.33;font-weight:700;color:#fff}
.mfp-floral-youth .ey-stats span{display:block;font-size:11px;line-height:1.4;color:rgba(255,255,255,.6)}
.mfp-floral-youth .ey-stats i{display:block;flex:0 0 1px;width:1px;height:32px;background:rgba(255,255,255,.15)}
/* ---------- PANEL ---------- */
.mfp-floral-youth .ey-panel{display:flex;flex-direction:column;min-width:0;background:var(--fy-ivory);padding:32px 20px}
.mfp-floral-youth .ey-progress{height:3px;width:100%;overflow:hidden;border-radius:999px;background:var(--fy-cream);margin-bottom:22px}
.mfp-floral-youth .ey-progress i{display:block;height:100%;width:25%;border-radius:999px;background:linear-gradient(90deg,var(--fy-blush),var(--fy-rose));transition:width .5s ease}
.mfp-floral-youth .ey-stepper{display:flex;align-items:flex-start;gap:4px;margin-bottom:28px}
.mfp-floral-youth .ey-step{display:flex;flex-direction:column;align-items:center;flex:0 0 auto;text-align:center}
.mfp-floral-youth .ey-dot{display:flex;align-items:center;justify-content:center;flex:0 0 32px;width:32px;height:32px;border:2px solid var(--fy-line);border-radius:999px;background:var(--fy-cream);color:var(--fy-mut);font-size:12px;font-weight:600;letter-spacing:.02em;transition:all .18s ease}
.mfp-floral-youth .ey-step.is-active .ey-dot{background:var(--fy-blush);border-color:var(--fy-blush);color:#fff}
.mfp-floral-youth .ey-step.is-done .ey-dot{background:var(--fy-rose);border-color:var(--fy-rose);color:#fff}
.mfp-floral-youth .ey-step-text{display:none;margin-top:4px}
.mfp-floral-youth .ey-step-text strong{display:block;font-size:11px;font-weight:600;color:var(--fy-mut)}
.mfp-floral-youth .ey-step.is-active .ey-step-text strong,.mfp-floral-youth .ey-step.is-done .ey-step-text strong{color:var(--fy-ink)}
.mfp-floral-youth .ey-step-text span{display:block;font-size:10px;line-height:1.4;color:var(--fy-mut)}
.mfp-floral-youth .ey-line{flex:1 1 auto;height:1px;margin:16px 6px 0;background:var(--fy-line);transition:background .18s ease}
.mfp-floral-youth .ey-line.is-done{background:var(--fy-rose)}
/* ---------- CARD (white, rounded, floral corners) ---------- */
.mfp-floral-youth .ey-card{position:relative;flex:1;overflow:hidden;border:1px solid var(--fy-line);border-radius:24px;background:#fff;box-shadow:0 10px 15px -3px rgba(61,37,53,.08),0 4px 6px -4px rgba(61,37,53,.06);padding:24px}
.mfp-floral-youth .ey-card::before{content:'';position:absolute;top:-8px;right:-8px;z-index:0;width:176px;height:160px;opacity:.7;pointer-events:none;background-repeat:no-repeat;background-position:center;background-size:contain;background-image:url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 220 200'><ellipse cx='175' cy='42' rx='34' ry='22' fill='%23f9c8d8' transform='rotate(-30 175 42)'/><ellipse cx='162' cy='28' rx='28' ry='18' fill='%23f4aec8' transform='rotate(-55 162 28)'/><ellipse cx='192' cy='30' rx='26' ry='16' fill='%23f9c8d8' transform='rotate(-10 192 30)'/><ellipse cx='180' cy='55' rx='22' ry='14' fill='%23fbdce8' transform='rotate(20 180 55)'/><ellipse cx='155' cy='50' rx='20' ry='13' fill='%23f4aec8' transform='rotate(-70 155 50)'/><circle cx='175' cy='38' r='11' fill='%23e07090'/><circle cx='175' cy='38' r='6' fill='%23c8507a'/><ellipse cx='140' cy='20' rx='14' ry='9' fill='%23f9c8d8' transform='rotate(-40 140 20)'/><ellipse cx='132' cy='14' rx='10' ry='7' fill='%23f4aec8' transform='rotate(-60 132 14)'/><circle cx='140' cy='18' r='5' fill='%23e07090'/><ellipse cx='145' cy='68' rx='28' ry='9' fill='%23a8d0a8' transform='rotate(-50 145 68)' opacity='.7'/><ellipse cx='200' cy='68' rx='22' ry='8' fill='%2390c890' transform='rotate(30 200 68)' opacity='.6'/><ellipse cx='118' cy='42' rx='20' ry='7' fill='%23a8d0a8' transform='rotate(-80 118 42)' opacity='.65'/><ellipse cx='108' cy='10' rx='8' ry='5' fill='%23c8a8e0' transform='rotate(-20 108 10)'/><ellipse cx='118' cy='6' rx='7' ry='4' fill='%23d4b8ec' transform='rotate(-10 118 6)'/><ellipse cx='128' cy='4' rx='6' ry='3.5' fill='%23c8a8e0' transform='rotate(5 128 4)'/><path d='M118 12 115 30' stroke='%2390c890' stroke-width='1.5' opacity='.7'/></svg>")}
.mfp-floral-youth .ey-card::after{content:'';position:absolute;bottom:-8px;left:-8px;z-index:0;width:160px;height:144px;opacity:.65;pointer-events:none;background-repeat:no-repeat;background-position:center;background-size:contain;background-image:url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 200 180'><ellipse cx='45' cy='145' rx='30' ry='20' fill='%23f9c8d8' transform='rotate(25 45 145)'/><ellipse cx='60' cy='160' rx='26' ry='17' fill='%23f4aec8' transform='rotate(50 60 160)'/><ellipse cx='28' cy='158' rx='24' ry='15' fill='%23fbdce8' transform='rotate(-10 28 158)'/><ellipse cx='55' cy='132' rx='20' ry='13' fill='%23f9c8d8' transform='rotate(-30 55 132)'/><circle cx='46' cy='148' r='10' fill='%23e07090'/><circle cx='46' cy='148' r='5' fill='%23c8507a'/><ellipse cx='85' cy='168' rx='13' ry='8' fill='%23f9c8d8' transform='rotate(40 85 168)'/><ellipse cx='92' cy='176' rx='10' ry='6' fill='%23f4aec8' transform='rotate(55 92 176)'/><circle cx='85' cy='167' r='4' fill='%23e07090'/><ellipse cx='22' cy='120' rx='26' ry='8' fill='%23a8d0a8' transform='rotate(60 22 120)' opacity='.7'/><ellipse cx='75' cy='122' rx='20' ry='7' fill='%2390c890' transform='rotate(-40 75 122)' opacity='.6'/><ellipse cx='10' cy='148' rx='7' ry='4' fill='%23c8a8e0' transform='rotate(-15 10 148)'/><ellipse cx='18' cy='140' rx='6' ry='4' fill='%23d4b8ec' transform='rotate(-5 18 140)'/><path d='M15 135 12 115' stroke='%2390c890' stroke-width='1.5' opacity='.7'/></svg>")}
/* ---------- PAGES ---------- */
.mfp-floral-youth .ey-page{display:none;position:relative;z-index:1}
.mfp-floral-youth .ey-page.is-active{display:block}
.mfp-floral-youth .ey-page .ey-eyebrow{margin:0 0 4px;font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--fy-blush)}
.mfp.mfp-floral-youth .ey-page .ey-eyebrow{color:var(--fy-blush)!important}
.mfp-floral-youth .ey-page h2{margin:0;font-size:1.875rem;line-height:1.2;font-weight:700;color:var(--fy-ink)}
.mfp.mfp-floral-youth .ey-page h2{color:var(--fy-ink)!important}
.mfp-floral-youth .ey-lede{margin:4px 0 0;font-size:14px;line-height:1.45;color:var(--fy-mut)}
.mfp-floral-youth .ey-lede::after{content:'';display:block;height:22px;margin-top:10px;background-repeat:no-repeat,no-repeat;background-position:center center,center center;background-size:22px 22px,100% 1px;background-image:url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='12' fill='%23ffffff'/><circle cx='12' cy='7.4' r='3.1' fill='%23f2a7c0'/><circle cx='16.4' cy='10.6' r='3.1' fill='%23f2a7c0'/><circle cx='14.7' cy='15.8' r='3.1' fill='%23f2a7c0'/><circle cx='9.3' cy='15.8' r='3.1' fill='%23f2a7c0'/><circle cx='7.6' cy='10.6' r='3.1' fill='%23f2a7c0'/><circle cx='12' cy='12' r='2.4' fill='%23e07090'/></svg>"),linear-gradient(var(--fy-line),var(--fy-line))}
.mfp-floral-youth .ey-mt5{margin-top:20px}
.mfp-floral-youth .ey-mt6{margin-top:20px}
.mfp-floral-youth .ey-grid{display:grid;gap:16px}
.mfp-floral-youth .ey-grid-2{grid-template-columns:1fr}
/* ---------- FIELDS ---------- */
.mfp-floral-youth .ey-field{display:block}
.mfp-floral-youth .ey-field>span{display:block;margin-bottom:6px;font-size:12px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:var(--fy-mut)}
.mfp-floral-youth .mf-field-group{margin:0}
.mfp.mfp-floral-youth .ey-field .mf-field-label{display:none!important}
.mfp.mfp-floral-youth .ey-field .mf-input,.mfp.mfp-floral-youth .ey-field .mf-select,.mfp.mfp-floral-youth .ey-field .mf-textarea,.mfp.mfp-floral-youth .ey-field input[type=text],.mfp.mfp-floral-youth .ey-field input[type=email],.mfp.mfp-floral-youth .ey-field input[type=tel],.mfp.mfp-floral-youth .ey-field input[type=number],.mfp.mfp-floral-youth .ey-field input[type=date],.mfp.mfp-floral-youth .ey-field select,.mfp.mfp-floral-youth .ey-field textarea{width:100%!important;max-width:100%!important;border:1.5px solid var(--fy-line)!important;border-radius:14px!important;background:#fff!important;box-shadow:none!important;padding:12px 16px!important;font-size:15px!important;line-height:1.4!important;color:var(--fy-ink)!important;outline:none!important;transition:border-color .18s ease,box-shadow .18s ease}
.mfp.mfp-floral-youth .ey-field .mf-input:focus,.mfp.mfp-floral-youth .ey-field .mf-select:focus,.mfp.mfp-floral-youth .ey-field .mf-textarea:focus,.mfp.mfp-floral-youth .ey-field input:focus,.mfp.mfp-floral-youth .ey-field select:focus,.mfp.mfp-floral-youth .ey-field textarea:focus{border-color:var(--fy-blush)!important;box-shadow:0 0 0 3px var(--fy-ring)!important}
.mfp.mfp-floral-youth .ey-field .mf-input::placeholder,.mfp.mfp-floral-youth .ey-field input::placeholder,.mfp.mfp-floral-youth .ey-field .mf-textarea::placeholder,.mfp.mfp-floral-youth .ey-field textarea::placeholder{color:#cbb3c0!important;opacity:1}
.mfp.mfp-floral-youth .ey-field .mf-select,.mfp.mfp-floral-youth .ey-field select{-webkit-appearance:none!important;-moz-appearance:none!important;appearance:none!important;padding-right:40px!important;background-color:#fff!important;background-repeat:no-repeat!important;background-position:right 14px center!important;background-size:16px 16px!important;background-image:url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%238d6a7a' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='m6 9 6 6 6-6'/></svg>")!important}
.mfp.mfp-floral-youth .ey-field textarea,.mfp.mfp-floral-youth .ey-field .mf-textarea{min-height:118px!important;resize:none!important}
.mfp.mfp-floral-youth .ey-field .mf-field-error{margin-top:6px;font-size:12px;color:var(--fy-rose)}
.mfp.mfp-floral-youth .mf-option-control{position:absolute!important;opacity:0!important;width:0!important;height:0!important;pointer-events:none!important}
/* ---- CHIPS (interests): horizontal wrap pills ---- */
.mfp.mfp-floral-youth .mf-option-group--chips{display:flex!important;flex-wrap:wrap!important;gap:8px!important;grid-template-columns:none!important;margin-top:2px}
.mfp.mfp-floral-youth .mf-option-item--chips{margin:0!important;width:auto!important;cursor:pointer}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-ui{display:inline-flex;align-items:center;gap:6px;border:1.5px solid var(--fy-line);border-radius:999px;background:#fff;padding:6px 14px;font-size:14px;font-weight:500;color:var(--fy-mut);box-shadow:none;transition:all .18s ease}
.mfp.mfp-floral-youth .mf-option-item--chips:hover .mf-option-ui{border-color:var(--fy-blush)}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-control:checked+.mf-option-ui{background:var(--fy-blush);border-color:var(--fy-blush);color:#fff}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-icon{display:none!important}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-desc{display:none!important}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-badge{display:none!important}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-check,.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-control:checked+.mf-option-ui .mf-option-check{display:none!important}
.mfp.mfp-floral-youth .mf-option-item--chips .mf-option-label{font-size:14px;font-weight:500;color:inherit}
/* ---- CARDS (programme): icon tile + copy + location badge ---- */
.mfp.mfp-floral-youth .mf-option-group--cards{display:grid!important;grid-template-columns:1fr!important;gap:12px!important;margin-top:2px}
.mfp.mfp-floral-youth .mf-option-item--cards{margin:0!important;cursor:pointer}
.mfp.mfp-floral-youth .mf-option-item--cards .mf-option-ui{display:flex;align-items:flex-start;gap:16px;border:1.5px solid var(--fy-line);border-radius:16px;background:#fff;padding:16px;box-shadow:none;transition:all .18s ease}
.mfp.mfp-floral-youth .mf-option-item--cards:hover .mf-option-ui{border-color:var(--fy-blush)}
.mfp.mfp-floral-youth .mf-option-item--cards .mf-option-control:checked+.mf-option-ui{border-color:var(--fy-blush);background:var(--fy-blush-soft);box-shadow:0 0 0 3px var(--fy-ring)}
.mfp.mfp-floral-youth .mf-option-icon{display:flex;align-items:center;justify-content:center;flex:0 0 44px;width:44px;height:44px;border-radius:12px;background:var(--fy-cream);color:var(--fy-rose);font-size:20px;line-height:1;transition:all .18s ease}
.mfp.mfp-floral-youth .mf-option-item--cards .mf-option-control:checked+.mf-option-ui .mf-option-icon{background:var(--fy-blush);color:#fff}
.mfp.mfp-floral-youth .mf-option-copy{flex:1 1 auto;min-width:0}
.mfp.mfp-floral-youth .mf-option-label{display:block;font-size:15px;font-weight:600;line-height:1.35;color:var(--fy-ink)}
.mfp.mfp-floral-youth .mf-option-desc{display:block;margin-top:4px;font-size:14px;line-height:1.5;color:var(--fy-mut)}
.mfp.mfp-floral-youth .mf-option-badge{align-self:flex-start;flex:0 0 auto;border-radius:999px;background:var(--fy-lav-soft);padding:3px 10px;font-size:11px;font-weight:700;letter-spacing:.03em;line-height:1.5;color:var(--fy-lav-ink);white-space:nowrap}
.mfp.mfp-floral-youth .mf-option-check{display:none!important;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:var(--fy-rose)}
.mfp.mfp-floral-youth .mf-option-control:checked+.mf-option-ui .mf-option-check{display:inline-flex!important}
/* accommodation cards = compact, no icon, no badge, no check, 3 across on >=640 */
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-item--cards .mf-option-ui{display:block;padding:16px}
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-icon{display:none!important}
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-badge{display:none!important}
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-check,.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-control:checked+.mf-option-ui .mf-option-check{display:none!important}
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-label{font-size:14px}
.mfp.mfp-floral-youth [data-key='accommodation'] .mf-option-desc{margin-top:2px;font-size:12px}
/* ---- plain checkbox rows (scholarship / newsletter / terms) ---- */
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards){display:grid!important;gap:12px!important;grid-template-columns:none!important;margin-top:2px}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-item{cursor:pointer}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui{display:flex;align-items:flex-start;gap:12px;font-size:14px;line-height:1.5;color:var(--fy-mut)}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-ui::before{content:'';flex:0 0 20px;width:20px;height:20px;margin-top:1px;border:1.5px solid var(--fy-line);border-radius:6px;background:#fff;transition:all .18s ease}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-control:checked+.mf-option-ui::before{background:var(--fy-rose);border-color:var(--fy-rose);box-shadow:inset 0 0 0 3px #fff}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-icon{display:none!important}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-badge{display:none!important}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-label{font-size:14px;font-weight:400;line-height:1.5;color:var(--fy-mut)}
.mfp.mfp-floral-youth .mf-option-group:not(.mf-option-group--chips):not(.mf-option-group--cards) .mf-option-desc{font-size:12px;color:var(--fy-mut)}
